        d = date(2024, 1, 3)
        assert business_days_between(d, d) == 0

    def test_same_day_weekend_returns_zero(self):
        d = date(2024, 1, 6)
        assert business_days_between(d, d) == 0

    @pytest.mark.parametrize(
        "start, end",
        [
            (date(2024, 1, 8), date(2024, 1, 1)),
            (date(2024, 1, 2), date(2024, 1, 1)),
            (date(2025, 1, 1), date(2024, 1, 1)),
        ],
    )
    def test_start_after_end_returns_zero(self, start, end):
        assert business_days_between(start, end) == 0


