Here's a test file for `business_days_between`. The function counts weekdays in the half-open interval `[start, end)`, so start is included, end is excluded, and any reversed range returns 0. The tests pin down that behavior.

```python
from datetime import date, timedelta

import pytest

from date_utils import business_days_between  # adjust to your module path

# Reference calendar (Jan 2024), used throughout:
#   Mon 01-01  Tue 01-02  Wed 01-03  Thu 01-04  Fri 01-05  Sat 01-06  Sun 01-07
#   Mon 01-08  ...


def test_reference_calendar_assumption():
    # Guards the hard-coded dates below against typos.
    assert date(2024, 1, 1).weekday() == 0  # Monday


class TestBasics:
    def test_same_day_returns_zero(self):
        d = date(2024, 1, 1)
        assert business_days_between(d, d) == 0

    def test_consecutive_weekdays(self):
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 2)) == 1

    def test_monday_to_friday_excludes_end_day(self):
        # Mon, Tue, Wed, Thu counted; Fri (end) excluded
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 5)) == 4

    def test_monday_to_saturday_counts_full_work_week(self):
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 6)) == 5

    def test_monday_to_next_monday(self):
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 8)) == 5

    def test_two_full_weeks(self):
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 15)) == 10


class TestWeekends:
    @pytest.mark.parametrize(
        "start, end, expected",
        [
            (date(2024, 1, 5), date(2024, 1, 8), 1),   # Fri -> Mon: only Fri counts
            (date(2024, 1, 6), date(2024, 1, 8), 0),   # Sat -> Mon
            (date(2024, 1, 6), date(2024, 1, 7), 0),   # Sat -> Sun
            (date(2024, 1, 7), date(2024, 1, 8), 0),   # Sun -> Mon
            (date(2024, 1, 6), date(2024, 1, 13), 5),  # Sat -> Sat
            (date(2024, 1, 7), date(2024, 1, 14), 5),  # Sun -> Sun
        ],
        ids=[
            "fri_to_mon",
            "sat_to_mon",
            "sat_to_sun",
            "sun_to_mon",
            "sat_to_next_sat",
            "sun_to_next_sun",
        ],
    )
    def test_weekend_boundaries(self, start, end, expected):
        assert business_days_between(start, end) == expected

    def test_weekend_only_range_is_zero(self):
        assert business_days_between(date(2024, 1, 6), date(2024, 1, 8)) == 0


class TestReversedRange:
    def test_end_before_start_returns_zero(self):
        assert business_days_between(date(2024, 1, 8), date(2024, 1, 1)) == 0

    def test_end_one_day_before_start_returns_zero(self):
        assert business_days_between(date(2024, 1, 2), date(2024, 1, 1)) == 0


class TestCalendarEdges:
    def test_crosses_year_boundary(self):
        # Fri 2023-12-29 and Mon 2024-01-01 counted; weekend skipped; Tue excluded
        assert business_days_between(date(2023, 12, 29), date(2024, 1, 2)) == 2

    def test_includes_leap_day(self):
        # Wed 2024-02-28, Thu 2024-02-29 counted; Fri 03-01 excluded
        assert business_days_between(date(2024, 2, 28), date(2024, 3, 1)) == 2

    def test_non_leap_february(self):
        # Tue 2023-02-28 counted; Wed 03-01 excluded
        assert business_days_between(date(2023, 2, 28), date(2023, 3, 1)) == 1

    def test_full_leap_year(self):
        # 366 days = 52 weeks + Mon + Tue -> 52*5 + 2
        assert business_days_between(date(2024, 1, 1), date(2025, 1, 1)) == 262

    def test_full_non_leap_year(self):
        # 2023: 365 days = 52 weeks + 1 extra Sunday -> 52*5
        assert business_days_between(date(2023, 1, 1), date(2024, 1, 1)) == 260


class TestProperties:
    """Invariants that should hold for any inputs, checked over a sweep of dates."""

    STARTS = [date(2024, 1, 1) + timedelta(days=i) for i in range(14)]
    OFFSETS = range(0, 30)

    def test_result_is_bounded_by_calendar_days(self):
        for start in self.STARTS:
            for n in self.OFFSETS:
                end = start + timedelta(days=n)
                assert 0 <= business_days_between(start, end) <= n

    def test_additive_over_split_point(self):
        for start in self.STARTS:
            for n in self.OFFSETS:
                for m in range(0, n + 1, 3):
                    mid = start + timedelta(days=m)
                    end = start + timedelta(days=n)
                    assert business_days_between(start, end) == (
                        business_days_between(start, mid)
                        + business_days_between(mid, end)
                    )

    def test_any_seven_day_window_has_five_business_days(self):
        for start in self.STARTS:
            assert business_days_between(start, start + timedelta(days=7)) == 5
```

Notes:

- **Half-open interval:** The `[start, end)` semantics are the most likely thing to change by accident, so several tests (`monday_to_friday_excludes_end_day`, `fri_to_mon`) pin them down explicitly. If you intended an inclusive end, the function is the thing to fix, not the tests.
- **Holidays:** The function ignores them, and I didn't write tests implying otherwise.
- **Hard-coded expected values:** I computed them by hand from the Jan 2024 calendar rather than re-implementing the logic, so the tests don't just mirror the code. The `test_reference_calendar_assumption` guard catches a bad anchor date.
- **`datetime` inputs:** I didn't test them. The function would technically work with `datetime` objects, but the type hint says `date`.
- **The other 39 functions:** The same layout should carry over: a class per behavior area, parametrized edge cases, and a small property-style sweep where there are clear invariants. If you paste the next few, I can follow the same conventions.
